INSERT INTO weekly_market_calendar (hs_id,hs_path,hs_created_at,hs_name,hs_child_table_id,hs_updated_at,week_slug,main_title,page_subtitle,page_date,week_start_date,week_end_date,cover_image,description,ai_summary,body) VALUES (371545596637,'2026-06-22','2026-07-21 08:30:45','จับตาสัปดาห์นี้: PMI แฟลช, GDP สหรัฐฯ ขั้นสุดท้าย, Core PCE และผลประกอบการ Micron',0,'2026-07-23 03:53:42','2026-06-22','จับตาสัปดาห์นี้: PMI แฟลช, GDP สหรัฐฯ ขั้นสุดท้าย, Core PCE และผลประกอบการ Micron','ปฏิทินเศรษฐกิจและนัยต่อตลาดการเงิน 22–26 มิถุนายน 2569','2026-06-22','2026-06-22','2026-06-26',NULL,'สัปดาห์แห่งตัวเลขชี้วัดเศรษฐกิจจากทั่วโลก — PMI แฟลช, GDP ขั้นสุดท้าย, Core PCE และผลประกอบการชิปชั้นนำ ล้วนพร้อมส่งสัญญาณทิศทางตลาด','<p><span>ในสัปดาห์ที่ 22–26 มิถุนายน 2569 ตลาดจะจับตาตัวเลข PMI แฟลชเดือนมิถุนายนของสหรัฐฯ ยูโรโซน และญี่ปุ่น เพื่อประเมินโมเมนตัมภาคการผลิตและบริการทั่วโลก โดยฉันทามติ US Manufacturing PMI อยู่ที่ 54.7 ต่ำกว่าค่าเดิม 55.1 สะท้อนความเสี่ยงชะลอตัวเล็กน้อย</span></p><p><span>ปลายสัปดาห์นักลงทุนจะรับทราบ GDP Growth QoQ 1Q26 ขั้นสุดท้ายและ Core PCE MoM เดือนพฤษภาคมของสหรัฐฯ ซึ่งเป็นตัวชี้วัดเงินเฟ้อหลักของ Fed พร้อมผลการ Stress Test ธนาคารพาณิชย์สหรัฐฯ และงบการเงินของ Micron และ Trip.com ในคืนวันพุธ</span></p>','<h3><span>ปฏิทินเศรษฐกิจและเหตุการณ์สำคัญประจำสัปดาห์ 22–26 มิถุนายน 2569</span></h3><div style=''overflow-x:auto;-webkit-overflow-scrolling:touch;''><table style=''width:100%;border-collapse:collapse;table-layout:fixed;font-family:''Noto Sans Thai'',sans-serif;font-size:12px;border:1px solid #d4d9e0;margin:10px 0;''><thead><tr><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>วันที่</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>ประเภท</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>Economics /