INSERT INTO weekly_market_calendar (hs_id,hs_path,hs_created_at,hs_name,hs_child_table_id,hs_updated_at,week_slug,main_title,page_subtitle,page_date,week_start_date,week_end_date,cover_image,description,ai_summary,body) VALUES (377465030385,'2026-04-27','2026-08-04 04:58:29','จับตาสัปดาห์นี้: BOJ, Fed และ BOE ประชุมดอกเบี้ย พร้อม GDP สหรัฐฯ และผลประกอบการบริษัทเทคโนโลยีระดับโลก',0,'2026-08-04 04:58:29','2026-04-27','จับตาสัปดาห์นี้: BOJ, Fed และ BOE ประชุมดอกเบี้ย พร้อม GDP สหรัฐฯ และผลประกอบการบริษัทเทคโนโลยีระดับโลก','ปฏิทินเศรษฐกิจและนัยต่อตลาดการเงิน 27 เมษายน – 1 พฤษภาคม 2569','2026-04-27','2026-04-27','2026-05-01',NULL,'สัปดาห์แห่งการตัดสินใจครั้งสำคัญ ธนาคารกลางสามแห่งพร้อมกัน บวกกับผลประกอบการยักษ์ใหญ่เทคโนโลยีโลก','<p><span>สัปดาห์ที่ 27 เมษายน – 1 พฤษภาคม 2569 เป็นสัปดาห์ที่มีเหตุการณ์สำคัญหนาแน่น โดยเฉพาะการประชุมอัตราดอกเบี้ยของ BOJ (0.75%), Fed (3.75%) และ BOE (3.75%) พร้อมกัน ซึ่งจะเป็นตัวกำหนดทิศทางตลาดพันธบัตรและค่าเงินทั่วโลก</span></p><p><span>ในฝั่งเศรษฐกิจจริง GDP สหรัฐฯ ไตรมาสแรก (consensus 1.8% จากเดิม 0.5%) และ PMI ภาคการผลิตจีนจะสะท้อนแรงส่งเศรษฐกิจโลก ขณะที่ผลประกอบการของ Amazon, Microsoft, Meta, Google, Apple และ Samsung Electronics จะเป็นปัจจัยชี้นำหุ้นกลุ่มเทคโนโลยีในสัปดาห์นี้</span></p>','<h3><span>ปฏิทินเศรษฐกิจและเหตุการณ์สำคัญประจำสัปดาห์ 27 เมษายน – 1 พฤษภาคม 2569</span></h3><div style=''overflow-x:auto;-webkit-overflow-scrolling:touch;''><table style=''width:100%;border-collapse:collapse;table-layout:fixed;font-family:''Noto Sans Thai'',sans-serif;font-size:12px;border:1px solid #d4d9e0;margin:10px 0;''><thead><tr><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>วันที่</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>ประเภท</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;'