INSERT INTO weekly_market_calendar (hs_id,hs_path,hs_created_at,hs_name,hs_child_table_id,hs_updated_at,week_slug,main_title,page_subtitle,page_date,week_start_date,week_end_date,cover_image,description,ai_summary,body) VALUES (379669796543,'2026-08-10','2026-08-10 01:52:58','จับตาสัปดาห์นี้: ตัวเลข CPI/PPI สหรัฐฯ พร้อมผลประกอบการยักษ์ใหญ่เทคโนโลยีและจีน',0,'2026-08-10 01:52:58','2026-08-10','จับตาสัปดาห์นี้: ตัวเลข CPI/PPI สหรัฐฯ พร้อมผลประกอบการยักษ์ใหญ่เทคโนโลยีและจีน','ปฏิทินเศรษฐกิจและนัยต่อตลาดการเงิน 10–14 สิงหาคม 2569','2026-08-10','2026-08-10','2026-08-14',NULL,'สัปดาห์ร้อนแรงกลางเดือนสิงหา ลุ้น CPI สหรัฐฯ ชี้ชะตาดอกเบี้ย พร้อมงบการเงินเทคฯ ทั้งสองฝั่งมหาสมุทร','<p><span>สัปดาห์ที่ 10–14 สิงหาคม 2569 มีเหตุการณ์สำคัญหลายด้าน ได้แก่ การเปิดเผย BOJ Summary of Opinions ของญี่ปุ่น และตัวเลข Core CPI สหรัฐฯ เดือนกรกฎาคม ซึ่งตลาดคาดไว้ที่ 2.5% YoY (ลดลงจาก 2.6%) และ 0.2% MoM อันเป็นสัญญาณสำคัญต่อแนวโน้มนโยบายการเงิน Fed</span></p><p><span>นอกจากนี้ยังมีผลประกอบการบริษัทเทคโนโลยีและเซมิคอนดักเตอร์ชั้นนำ อาทิ Tencent, Cisco, AMAT, JD.com, SMIC รวมถึง TSMC Monthly Revenue เดือนกรกฎาคม ซึ่งล้วนเป็นตัวบ่งชี้ทิศทางความต้องการในห่วงโซ่อุปทานชิปและ AI ที่นักลงทุนควรติดตามอย่างใกล้ชิด</span></p><p><span>ข้อมูล US Retail Sales MoM กรกฎาคม (คาด 0.2%) และ Michigan Consumer Sentiment เบื้องต้นเดือนสิงหาคม (คาด 54.6 จากเดิม 55.2) จะสะท้อนความแข็งแกร่งของผู้บริโภคสหรัฐฯ และอาจส่งผลต่อสินทรัพย์ในกลุ่ม Consumer Discretionary และตลาดหุ้นโดยรวม</span></p>','<h3><span>ปฏิทินเศรษฐกิจและเหตุการณ์สำคัญประจำสัปดาห์ 10–14 สิงหาคม 2569</span></h3><div style=''overflow-x:auto;-webkit-overflow-scrolling:touch;''><table style=''width:100%;border-collapse:collapse;table-layout:fixed;font-family:''Noto Sans Thai'',sans-serif;font-size:12px;border:1px solid #d4d9e0;margin:10px 0;''><thead><tr><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>วันที่</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;t