INSERT INTO weekly_market_calendar (hs_id,hs_path,hs_created_at,hs_name,hs_child_table_id,hs_updated_at,week_slug,main_title,page_subtitle,page_date,week_start_date,week_end_date,cover_image,description,ai_summary,body) VALUES (386266348242,'2026-08-17','2026-08-25 02:41:28','จับตาสัปดาห์นี้: รายงาน GDP ญี่ปุ่น ตัวเลขเศรษฐกิจจีน รายงานการประชุม FOMC และผลประกอบการบริษัทชั้นนำ',0,'2026-08-25 02:41:28','2026-08-17','จับตาสัปดาห์นี้: รายงาน GDP ญี่ปุ่น ตัวเลขเศรษฐกิจจีน รายงานการประชุม FOMC และผลประกอบการบริษัทชั้นนำ','ปฏิทินเศรษฐกิจและนัยต่อตลาดการเงิน 17–21 สิงหาคม 2569','2026-08-17','2026-08-17','2026-08-21',NULL,'สัปดาห์แห่งตัวเลขชี้วัดเศรษฐกิจโลก ทั้งจีน ญี่ปุ่น และสหรัฐฯ พร้อมผลประกอบการยักษ์ใหญ่ที่ตลาดจับตา','<p><span>ในสัปดาห์ที่ 17–21 สิงหาคม 2569 นักลงทุนควรติดตามตัวเลข GDP เบื้องต้นของญี่ปุ่นไตรมาส 2 ที่ตลาดคาดไว้ที่ 2.0% และข้อมูลเศรษฐกิจจีนหลายรายการ ได้แก่ ยอดค้าปลีก การผลิตภาคอุตสาหกรรม และการลงทุนในสินทรัพย์ถาวร ซึ่งสะท้อนภาพการฟื้นตัวในประเทศที่ยังไม่สม่ำเสมอ</span></p><p><span>จุดเด่นกลางสัปดาห์คือการเผยแพร่รายงานการประชุม FOMC วันที่ 20 สิงหาคม ซึ่งตลาดจะประเมินทิศทางนโยบายการเงินสหรัฐฯ ขณะที่ผลประกอบการของ Alibaba, Walmart, Home Depot, Baidu และ Xiaomi จะเป็นสัญญาณสำคัญต่อกลุ่มค้าปลีกและเทคโนโลยี</span></p>','<h3><span>ปฏิทินเศรษฐกิจและเหตุการณ์สำคัญประจำสัปดาห์ 17–21 สิงหาคม 2569</span></h3><div style=''overflow-x:auto;-webkit-overflow-scrolling:touch;''><table style=''width:100%;border-collapse:collapse;table-layout:fixed;font-family:''Noto Sans Thai'',sans-serif;font-size:12px;border:1px solid #d4d9e0;margin:10px 0;''><thead><tr><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>วันที่</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;''>ประเภท</th><th style=''padding:8px 6px;background:#0c244a;color:#fff;text-align:center;font-weight:600;font-size:12px;border:1px solid #0c244a;'